 useEffect(()=>()=>report?.(id,false),[id,report]);
 function check(text){const n=Number(text.trim().replace(',','.'));return text.trim()===''?(optional?null:'Informe um valor.'):/^[+-]?(?:\d+(?:[.,]\d*)?|[.,]\d+)$/.test(text.trim())&&Number.isFinite(n)&&n>=min&&n<=max&&(!integer||Number.isInteger(n))?null:`Use ${integer?'um inteiro':'um número'} entre ${fmt(min)} e ${fmt(max)}.`}
